    li t0, 6
    bne a0, t0, fail
    addi s0, s0, 1
    addi s1, s1, 1

    # test 4: h(p=100, o=100) == 8
    li a0, 100
    li a1, 100
    jal ra, heuristic
    li t0, 8
    bne a0, t0, fail
    addi s0, s0, 1

    la a0, msg_pass
    li a7, 4
    ecall
    mv a0, s0
    li a7, 1
    ecall
    la a0, newline
    li a7, 4
    ecall
    li a7, 10
    ecall

fail:
    la a0, msg_fail
    li a7, 4
    ecall
    mv a0, s1
    li a7, 1
    ecall
    la a0, newline
    li a7, 4
    ecall
    li a7, 10
    ecall

# heuristic(a0=p, a1=o) -> a0=max(h_perm, h_pdb)
# Uses only RV32I instructions (la/li/mv/ret are assembler pseudos).
heuristic:
    slli t0, a0, 1        # byte offset = p * 2
    la   t1, perm_meta
    add  t0, t1, t0
    lhu  t2, 0(t0)        # t2 = [hp:8 | p3:8]
    andi t3, t2, 255      # p3
    srli t4, t2, 8        # hp

    slli t0, a1, 2        # o * sizeof(uint32_t)
    la   t1, pdb_row_offset
    add  t0, t1, t0
    lw   t5, 0(t0)        # packed-PDB row byte offset
    srli t6, t3, 1        # p3 / 2
    add  t5, t5, t6
    la   t1, pdb3_packed
    add  t5, t1, t5
    lbu  t5, 0(t5)        # byte holding two 4-bit distances

    andi t6, t3, 1        # even/odd p3
    slli t6, t6, 2        # shift = 0 or 4
    srl  t5, t5, t6
    andi t5, t5, 15       # hpdb

    bgeu t4, t5, heuristic_hp
    mv   a0, t5
    ret
heuristic_hp:
    mv   a0, t4
    ret
